package com.springmfg.ims.document.storage;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where document content lives. The database holds metadata only; the content sits behind this interface so the
 * local volume used today can be replaced by object storage (S3 or similar) without touching the document service.
 * Keys are generated by the storage, never taken from a client.
 */
public interface DocumentStorage {

    /** Streams the content into storage, computing size and SHA-256, and fails once it exceeds {@code maxBytes}. */
    StoredObject store(InputStream content, long maxBytes) throws IOException;

    InputStream open(String storageKey) throws IOException;

    /** Best-effort removal (rolled-back uploads); never throws for a missing object. */
    void delete(String storageKey);

    record StoredObject(String storageKey, long sizeBytes, String sha256) {
    }

    /** The content exceeded the size limit while being read. */
    class ContentTooLargeException extends IOException {
        public ContentTooLargeException(long maxBytes) {
            super("Content exceeds " + maxBytes + " bytes");
        }
    }
}
